{
  "up": "Select molecule_chembl_id AS compound_chembl_id, canonical_smiles, compound_key, pubmed_id_or_doi, assay_description, standard_type, standard_relation, standard_value, standard_units, activity_comment, target_chembl_id, target_name, target_organism From molecule_dictionary MD Join activities ACT ON MD.molregno = ACT.molregno Join assays ASY ON ACT.assay_id = ASY.assay_id Join target_dictionary TD ON ASY.tid = TD.tid Join compound_structures CS ON MD.molregno = CS.molregno Join docs DOC ON ACT.doc_id = DOC.doc_id Where MD.molregno IN (Select MD2.molregno From molecule_dictionary MD2 Join assays ASY2 ON MD2.molregno = ASY2.molregno Join activities ACT2 ON ASY2.assay_id = ACT2.assay_id Join target_dictionary TD2 ON ASY2.tid = TD2.tid Where TD2.pref_name = 'ATP‑dependent translocase ABCB1' And TD2.target_type = 'PROTEIN' And TD2.organism = 'Homo sapiens' And ACT2.standard_type = 'IC50' And ACT2.standard_units = 'nM' And ACT2.standard_relation = '=' And ACT2.standard_value IS NOT NULL And ACT2.pubmed_id IS NOT NULL Or ACT2.doi IS NOT NULL) And (ACT2.pubmed_id IS NOT NULL Or ACT2.doi IS NOT NULL) And (CS.canonical_smiles IS NOT NULL) Order By compound_chembl_id, canonical_smiles, compound_key, pubmed_id_or_doi, assay_description, standard_type, standard_relation, standard_value, standard_units, activity_comment, target_chembl_id, target_name, target_organism"
}
